changeSet.sql:
CREATE TABLE refresh_tokens ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash varchar(64) NOT NULL UNIQUE, issued_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz NULL, replaced_by uuid NULL REFERENCES refresh_tokens(id), revocation_reason varchar(50) NULL );
-- Active токены для конкретного user'а (вход в bulk revoke) CREATE INDEX idx_refresh_tokens_user ON refresh_tokens(user_id) WHERE revoked_at IS NULL;
-- Lookup по hash на каждый /auth/refresh - hot path CREATE INDEX idx_refresh_tokens_hash ON refresh_tokens(token_hash);
-- Future RefreshTokenCleanupJanitor scan по expired CREATE INDEX idx_refresh_tokens_expires ON refresh_tokens(expires_at) WHERE revoked_at IS NULL;
